207	  async create(persona: Persona): Promise<Persona> {
208	    let createdAt = new Date().toISOString();
209	    if (persona?.id) {
210	      try {
211	        const existingPersona = await this.read(persona.id);
212	        createdAt = existingPersona.createdAt
213	          ? existingPersona.createdAt
214	          : new Date().toISOString();
215	      } catch (error) {
216	        this.logger.error(error);
217	        createdAt = new Date().toISOString();
218	      }
219	    }
220	    const entity = new Persona(persona);
221	    entity.createdAt = createdAt;
222	    entity.updatedAt = new Date().toISOString();
223	    const storeData: StoreDataDto = {
224	      data: entity,
225	      context: {
226	        uniqueId: entity.id,
227	        documentType: documentType.PERSONA,
228	      },
229	    };
230	    await this.datastoreService.store(storeData);
231	    return entity;
232	  }
