228	    fieldKey: string,
229	    fieldValue: any,
230	    context: datastoreContext & { documentTypes?: documentType[] },
231	    pagination?: { page: number; pageSize: number },
232	  ): Promise<Record<any, any>[]> {
233	    const { documentType, documentTypes } = context;
234	
235	    // If documentTypes array is provided, search across multiple collections
236	    const collectionsToSearch = documentTypes
237	      ? documentTypes.map(
238	          (dt) => this.documentTypeToCollection(dt).collectionName,
239	        )
