284	  async getByFieldAndAggregate(
285	    fieldKey: string,
286	    fieldValue: any,
287	    context: datastoreContext & { documentTypes?: documentType[] },
288	    customAggregation: Array<any>,
289	    pagination?: { page: number; pageSize: number },
290	  ) {
291	    const { documentType, documentTypes } = context;
292	
293	    // Determine which collection(s) to search
294	    const collectionsToSearch = documentTypes
295	      ? documentTypes.map(
296	          (dt) => this.documentTypeToCollection(dt).collectionName,
297	        )
298	      : [this.documentTypeToCollection(documentType).collectionName];
299	
300	    this.logger.debug(
301	      `getByFieldAndAggregate: Searching collections ${collectionsToSearch.join(', ')} for ${fieldKey}=${fieldValue}.`,
302	    );
303	
304	    // Build a base pipeline that includes matching on the given fieldKey/fieldValue
305	    // then spread in any custom aggregation stages the caller provided.
306	    const buildPipeline = (scopedPagination?: {
307	      page: number;
308	      pageSize: number;
309	    }) => {
310	      const pipeline = [
311	        { $match: { [fieldKey]: fieldValue } },
312	        ...customAggregation,
313	      ];
314	
315	      // If pagination is requested, apply skip/limit at the end
316	      if (scopedPagination) {
317	        pipeline.push({
318	          $skip: scopedPagination.page * scopedPagination.pageSize,
319	        });
320	        pipeline.push({ $limit: scopedPagination.pageSize });
321	      }
322	
323	      return pipeline;
324	    };
325	
326	    // For each collection, run the aggregation pipeline
327	    const resultsPerCollection = await Promise.all(
328	      collectionsToSearch.map(async (collection) => {
329	        this.logger.debug(`Running aggregation on collection: ${collection}`);
330	
331	        const pipelineResult = await this.db
332	          .collection(collection)
333	          .aggregate(buildPipeline(pagination))
334	          .toArray();
335	
336	        // Optionally annotate results with the source collection
337	        return pipelineResult.map((doc) => ({
338	          ...doc,
339	          _collection: collection,
340	        }));
341	      }),
342	    );
343	
344	    // Flatten all results and return
345	    const allResults = resultsPerCollection.flat();
346	    return allResults;
347	  }
