349	  async migrate(SOURCE_COLLECTION, TARGET_COLLECTION) {
350	    try {
351	      const sourceCollection = this.db.collection(SOURCE_COLLECTION);
352	      const targetCollection = this.db.collection(TARGET_COLLECTION);
353	
354	      // Process documents in the source collection
355	      const cursor = sourceCollection.find();
356	      const BATCH_SIZE = 1000;
357	      let batch = [];
358	      let processedCount = 0;
359	
360	      while (await cursor.hasNext()) {
361	        const doc = await cursor.next();
362	
363	        // Transform campaignIds to the new format
364	        if (doc.data && doc.data.campaignIds) {
365	          const newDocument = {
366	            ...doc,
367	            data: {
368	              ...doc.data,
369	              campaignIds: Object.entries(doc.data.campaignIds).map(
370	                ([id, value]) => ({
371	                  id,
372	                  // eslint-disable-next-line
373	                  // @ts-ignore
374	                  ...value,
375	                }),
376	              ),
377	            },
378	          };
379	
380	          // Remove the _id field to avoid duplicate key errors in the new collection
381	          delete newDocument._id;
382	          batch.push(newDocument);
383	
384	          // Insert batch when full
385	          if (batch.length === BATCH_SIZE) {
386	            await targetCollection.insertMany(batch);
387	            processedCount += batch.length;
388	            this.logger.log(`Inserted ${processedCount} documents so far`);
389	            batch = [];
390	          }
391	        } else {
392	          this.logger.log(
393	            `Skipping document with missing data or campaignIds field: ${doc._id}`,
394	          );
395	        }
396	      }
397	
398	      // Insert remaining documents
399	      if (batch.length > 0) {
400	        await targetCollection.insertMany(batch);
401	        processedCount += batch.length;
402	      }
403	
404	      this.logger.log(
405	        `Transformation completed. Inserted ${processedCount} documents into ${TARGET_COLLECTION}.`,
406	      );
407	    } catch (error) {
408	      this.logger.error('An error occurred:', error);
409	    }
410	  }
