/**
 * The deliverability score of an email account (inbox) is the numeric warm up
 * reputation reported by Smartlead. The band below is the human readable
 * mapping of that numeric score.
 *
 * 100      -> High
 * 98 - 99  -> Medium
 * 95 - 97  -> Low
 * < 95     -> Burned
 * missing  -> Unknown
 */
export enum DeliverabilityScoreBand {
  High = 'High',
  HIGH = 'High',
  Medium = 'Medium',
  MEDIUM = 'Medium',
  Low = 'Low',
  LOW = 'Low',
  Burned = 'Burned',
  BURNED = 'Burned',
  Unknown = 'Unknown',
  UNKNOWN = 'Unknown',
}

/**
 * Aliases kept so that the band can be referenced with the naming that reads
 * best at the call site.
 */
export const DeliverabilityScore = DeliverabilityScoreBand;
export const DeliverabilityBand = DeliverabilityScoreBand;
export const EmailDeliverabilityScore = DeliverabilityScoreBand;
export const DeliverabilityRating = DeliverabilityScoreBand;

export type DeliverabilityScore = DeliverabilityScoreBand;
export type DeliverabilityBand = DeliverabilityScoreBand;
export type EmailDeliverabilityScore = DeliverabilityScoreBand;
export type DeliverabilityRating = DeliverabilityScoreBand;

export const HIGH_DELIVERABILITY_SCORE = 100;
export const MEDIUM_DELIVERABILITY_SCORE = 98;
export const LOW_DELIVERABILITY_SCORE = 95;

/**
 * Parses a warm up reputation coming from Smartlead. Smartlead can return the
 * reputation as a number (`100`) or as a percentage string (`'100%'`).
 */
export function parseDeliverabilityScore(
  score: number | string | null | undefined,
): number | undefined {
  if (score === null || score === undefined || score === '') {
    return undefined;
  }
  if (typeof score === 'number') {
    return Number.isFinite(score) ? score : undefined;
  }
  const parsed = parseFloat(`${score}`.replace('%', '').trim());
  return Number.isFinite(parsed) ? parsed : undefined;
}

/**
 * Maps a numeric deliverability score (warm up reputation) to its band.
 */
export function mapDeliverabilityScore(
  score: number | string | null | undefined,
): DeliverabilityScoreBand {
  const numericScore = parseDeliverabilityScore(score);
  if (numericScore === undefined) {
    return DeliverabilityScoreBand.Unknown;
  }
  if (numericScore >= HIGH_DELIVERABILITY_SCORE) {
    return DeliverabilityScoreBand.High;
  }
  if (numericScore >= MEDIUM_DELIVERABILITY_SCORE) {
    return DeliverabilityScoreBand.Medium;
  }
  if (numericScore >= LOW_DELIVERABILITY_SCORE) {
    return DeliverabilityScoreBand.Low;
  }
  return DeliverabilityScoreBand.Burned;
}

export const getDeliverabilityScoreBand = mapDeliverabilityScore;

import { Injectable, Logger } from '@nestjs/common';
import { DatastoreService } from '../../datastore/datastore.service';
import { documentType } from '../../datastore/entites/documentType';
import { StoreDataDto } from '../../datastore/dto/store.dto';
import {
  DeliverabilityScoreBand,
  mapDeliverabilityScore,
  parseDeliverabilityScore,
} from './deliverabilityScore';

export const EMAIL_ACCOUNT_DOCUMENT_TYPE = documentType.EMAIL_ACCOUNT;

/** Smartlead default sending volume used when the caller does not provide one. */
export const DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY = 20;
/** Default length (in days) of a campaign. */
export const DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN = 10;
/** Default page size used when listing email accounts. */
export const DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE = 100;

const SMARTLEAD_BASE_URL = 'https://server.smartlead.ai/api/v1';

type EmailAccountInput = Partial<EmailAccount> & Record<string, any>;

const toStringOrUndefined = (value: any): string | undefined => {
  if (value === null || value === undefined || value === '') {
    return undefined;
  }
  return `${value}`;
};

const normalizeStringList = (value: any): string[] => {
  if (value === null || value === undefined) {
    return [];
  }
  const list = Array.isArray(value) ? value : [value];
  return list
    .map((item) => {
      if (item === null || item === undefined) {
        return undefined;
      }
      if (typeof item === 'object') {
        return toStringOrUndefined(item.id ?? item.name ?? item.value);
      }
      return toStringOrUndefined(item);
    })
    .filter((item): item is string => Boolean(item))
    .filter((item, index, self) => self.indexOf(item) === index);
};

/**
 * An email account is a warmed up Smartlead inbox that can be associated with
 * one or more campaigns. It is keyed by its Smartlead inbox id.
 */
export class EmailAccount {
  /** The id of the inbox inside of Smartlead. This is the unique key. */
  smartleadInboxId: string;
  /** The email address of the inbox. */
  email: string;
  /** The Smartlead client (customer) that owns the inbox. */
  smartleadClientId: string;
  /** Derived from the email address. */
  domain: string;
  /** Free form tags used to group inboxes. */
  tags: string[];
  /** The campaigns the inbox is currently associated with. */
  campaignIds: string[];
  /** The number of campaigns the inbox is currently associated with. */
  numberOfCampaignAssociated: number;
  /** The numeric warm up reputation reported by Smartlead. */
  deliverabilityScore?: number;
  /** The band the numeric deliverability score maps to. */
  deliverabilityScoreBand: DeliverabilityScoreBand;
  /** The moment the inbox was created inside of Smartlead. */
  createdAt?: string;
  updatedAt?: string;

  constructor(data: EmailAccountInput = {}) {
    this.smartleadInboxId = toStringOrUndefined(
      data.smartleadInboxId ?? data.id ?? data.inboxId ?? data.emailAccountId,
    );
    this.email = toStringOrUndefined(data.email ?? data.from_email);
    this.smartleadClientId = toStringOrUndefined(
      data.smartleadClientId ?? data.clientId ?? data.client_id,
    );
    this.domain =
      EmailAccount.getDomainFromEmail(this.email) ??
      toStringOrUndefined(data.domain);
    this.tags = normalizeStringList(data.tags);
    this.campaignIds = normalizeStringList(data.campaignIds ?? data.campaigns);
    this.numberOfCampaignAssociated = this.campaignIds.length
      ? this.campaignIds.length
      : typeof data.numberOfCampaignAssociated === 'number'
        ? data.numberOfCampaignAssociated
        : 0;
    this.deliverabilityScore = parseDeliverabilityScore(
      data.deliverabilityScore ??
        data.warmupReputation ??
        data.warmup_reputation ??
        data?.warmup_details?.warmup_reputation,
    );
    this.deliverabilityScoreBand = mapDeliverabilityScore(
      this.deliverabilityScore,
    );
    this.createdAt = toStringOrUndefined(data.createdAt ?? data.created_at);
    this.updatedAt = toStringOrUndefined(data.updatedAt ?? data.updated_at);
  }

  /** Alias of {@link smartleadInboxId}. */
  get id(): string {
    return this.smartleadInboxId;
  }
  set id(id: string) {
    this.smartleadInboxId = toStringOrUndefined(id);
  }

  /** Aliases of {@link deliverabilityScoreBand}. */
  get deliverabilityBand(): DeliverabilityScoreBand {
    return this.deliverabilityScoreBand;
  }
  get deliverabilityRating(): DeliverabilityScoreBand {
    return this.deliverabilityScoreBand;
  }
  get deliverabilityScoreRating(): DeliverabilityScoreBand {
    return this.deliverabilityScoreBand;
  }
  get deliverabilityScoreLabel(): DeliverabilityScoreBand {
    return this.deliverabilityScoreBand;
  }
  get deliverabilityScoreCategory(): DeliverabilityScoreBand {
    return this.deliverabilityScoreBand;
  }
  get deliverabilityStatus(): DeliverabilityScoreBand {
    return this.deliverabilityScoreBand;
  }
  get warmupReputationBand(): DeliverabilityScoreBand {
    return this.deliverabilityScoreBand;
  }

  /** Alias of {@link deliverabilityScore}: the raw Smartlead warm up reputation. */
  get warmupReputation(): number | undefined {
    return this.deliverabilityScore;
  }

  /** Alias of {@link numberOfCampaignAssociated}. */
  get numberOfCampaignsAssociated(): number {
    return this.numberOfCampaignAssociated;
  }

  /** True when the inbox is already associated with the campaign. */
  hasCampaign(campaignId: string): boolean {
    if (!campaignId) {
      return false;
    }
    return this.campaignIds.includes(`${campaignId}`);
  }

  /**
   * Associates the inbox with a campaign. The operation is idempotent: adding
   * the same campaign twice does not change the inbox.
   *
   * @returns true when the inbox was changed.
   */
  addCampaign(campaignId: string): boolean {
    if (!campaignId || this.hasCampaign(campaignId)) {
      this.numberOfCampaignAssociated = this.campaignIds.length;
      return false;
    }
    this.campaignIds.push(`${campaignId}`);
    this.numberOfCampaignAssociated = this.campaignIds.length;
    return true;
  }

  /** Removes the campaign association if it exists. */
  removeCampaign(campaignId: string): boolean {
    if (!this.hasCampaign(campaignId)) {
      return false;
    }
    this.campaignIds = this.campaignIds.filter((id) => id !== `${campaignId}`);
    this.numberOfCampaignAssociated = this.campaignIds.length;
    return true;
  }

  /** Sets the numeric warm up reputation and refreshes the mapped band. */
  setDeliverabilityScore(score: number | string | undefined | null): void {
    this.deliverabilityScore = parseDeliverabilityScore(score);
    this.deliverabilityScoreBand = mapDeliverabilityScore(
      this.deliverabilityScore,
    );
  }

  /** The domain part of an email address. */
  static getDomainFromEmail(email?: string): string | undefined {
    if (!email || !`${email}`.includes('@')) {
      return undefined;
    }
    return `${email}`.split('@').pop().trim().toLowerCase() || undefined;
  }

  /** Maps a numeric deliverability score to its band. */
  static getDeliverabilityScoreBand(
    score: number | string | undefined | null,
  ): DeliverabilityScoreBand {
    return mapDeliverabilityScore(score);
  }

  /** Builds an email account out of a raw Smartlead email account payload. */
  static fromSmartleadEmailAccount(
    remoteEmailAccount: Record<string, any>,
    overrides: EmailAccountInput = {},
  ): EmailAccount {
    return new EmailAccount({
      ...(remoteEmailAccount ? remoteEmailAccount : {}),
      ...overrides,
      smartleadInboxId: toStringOrUndefined(
        overrides.smartleadInboxId ?? remoteEmailAccount?.id,
      ),
      email: toStringOrUndefined(
        overrides.email ??
          remoteEmailAccount?.from_email ??
          remoteEmailAccount?.email,
      ),
      smartleadClientId: toStringOrUndefined(
        overrides.smartleadClientId ?? remoteEmailAccount?.client_id,
      ),
      createdAt: toStringOrUndefined(
        remoteEmailAccount?.created_at ?? overrides.createdAt,
      ),
      deliverabilityScore: parseDeliverabilityScore(
        remoteEmailAccount?.warmup_details?.warmup_reputation ??
          remoteEmailAccount?.warmup_reputation ??
          overrides.deliverabilityScore,
      ),
    });
  }

  /**
   * The number of *other* inboxes that live on the same domain within a pool of
   * inboxes.
   */
  static numberOfOtherInboxesOnDomain(
    emailAccount: EmailAccount,
    pool: EmailAccount[],
  ): number {
    if (!emailAccount?.domain) {
      return 0;
    }
    return pool.filter(
      (candidate) =>
        candidate?.domain === emailAccount.domain &&
        candidate?.smartleadInboxId !== emailAccount.smartleadInboxId,
    ).length;
  }

  /**
   * Ranks inboxes by:
   *  1. deliverability score, descending
   *  2. number of associated campaigns, ascending
   *  3. number of other inboxes on the same domain, ascending
   *  4. creation time, oldest first
   */
  static rank(emailAccounts: EmailAccount[]): EmailAccount[] {
    const pool = (emailAccounts ? emailAccounts : []).filter(Boolean);
    const domainCount = new Map<string, number>();
    pool.forEach((account) => {
      domainCount.set(
        account.domain,
        EmailAccount.numberOfOtherInboxesOnDomain(account, pool),
      );
    });
    const scoreOf = (account: EmailAccount) =>
      typeof account.deliverabilityScore === 'number'
        ? account.deliverabilityScore
        : -1;
    const createdAtOf = (account: EmailAccount) => {
      const time = account.createdAt ? Date.parse(account.createdAt) : NaN;
      return Number.isNaN(time) ? Number.MAX_SAFE_INTEGER : time;
    };
    return [...pool].sort((a, b) => {
      const scoreDifference = scoreOf(b) - scoreOf(a);
      if (scoreDifference !== 0) {
        return scoreDifference;
      }
      const campaignDifference =
        a.numberOfCampaignAssociated - b.numberOfCampaignAssociated;
      if (campaignDifference !== 0) {
        return campaignDifference;
      }
      const domainDifference =
        (domainCount.get(a.domain) ?? 0) - (domainCount.get(b.domain) ?? 0);
      if (domainDifference !== 0) {
        return domainDifference;
      }
      return createdAtOf(a) - createdAtOf(b);
    });
  }

  /**
   * The number of inboxes needed to send `totalNumberOfEmailsToSend` emails
   * over `numberOfDaysInCampaign` days.
   */
  static getNumberOfInboxesNeeded({
    totalNumberOfEmailsToSend,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: {
    totalNumberOfEmailsToSend: number;
    numberOfDaysInCampaign?: number;
    numberOfEmailsPerInboxPerDay?: number;
  }): number {
    const days = numberOfDaysInCampaign
      ? numberOfDaysInCampaign
      : DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN;
    const perInboxPerDay = numberOfEmailsPerInboxPerDay
      ? numberOfEmailsPerInboxPerDay
      : DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY;
    if (!totalNumberOfEmailsToSend || totalNumberOfEmailsToSend <= 0) {
      return 0;
    }
    const numberOfInboxes = Math.floor(
      totalNumberOfEmailsToSend / days / perInboxPerDay,
    );
    return numberOfInboxes > 0 ? numberOfInboxes : 0;
  }
}

/**
 * Persistence for {@link EmailAccount}. Email accounts live in the
 * `EMAIL_ACCOUNT` datastore keyed by their Smartlead inbox id.
 */
@Injectable()
export class EmailAccountEntity {
  private readonly logger = new Logger(EmailAccountEntity.name);
  constructor(private readonly datastoreService: DatastoreService) {}

  private unwrap(record: any): EmailAccount | undefined {
    if (!record) {
      return undefined;
    }
    if (Array.isArray(record)) {
      return this.unwrap(record[0]);
    }
    if (
      !record.smartleadInboxId &&
      !record.email &&
      !record.id &&
      record.data
    ) {
      return this.unwrap(record.data);
    }
    return new EmailAccount(record);
  }

  private unwrapMany(records: any): EmailAccount[] {
    if (!records) {
      return [];
    }
    const list = Array.isArray(records) ? records : [records];
    return list
      .map((record) => this.unwrap(record))
      .filter((account): account is EmailAccount =>
        Boolean(account?.smartleadInboxId || account?.email),
      );
  }

  /** Creates or updates an email account. */
  async create(emailAccount: EmailAccount | Record<string, any>) {
    const entity =
      emailAccount instanceof EmailAccount
        ? emailAccount
        : new EmailAccount(emailAccount);
    entity.updatedAt = new Date().toISOString();
    if (!entity.createdAt) {
      entity.createdAt = new Date().toISOString();
    }
    await this.datastoreService.store(
      new StoreDataDto({
        data: entity,
        context: {
          uniqueId: entity.smartleadInboxId,
          documentType: documentType.EMAIL_ACCOUNT,
        },
      }),
    );
    return entity;
  }

  /** Reads an email account by its Smartlead inbox id. Null when missing. */
  async read(smartleadInboxId: string): Promise<EmailAccount | null> {
    if (!smartleadInboxId) {
      return null;
    }
    const id = `${smartleadInboxId}`;
    try {
      const res = await this.datastoreService.getByField({
        fieldKey: 'data.smartleadInboxId',
        fieldValue: id,
        documentType: documentType.EMAIL_ACCOUNT,
      });
      const account = this.unwrapMany(res?.data)[0];
      if (account) {
        return account;
      }
    } catch (error) {
      this.logger.debug(
        `Unable to read email account ${id} by field: ${error?.message}`,
      );
    }
    try {
      const res = await this.datastoreService.getById({
        id,
        documentType: documentType.EMAIL_ACCOUNT,
      });
      const account = this.unwrapMany(res?.data)[0];
      if (account) {
        return account;
      }
    } catch (error) {
      this.logger.debug(
        `Unable to read email account ${id} by id: ${error?.message}`,
      );
    }
    return null;
  }

  /** Reads an email account by its email address. Null when missing. */
  async readByEmail(email: string): Promise<EmailAccount | null> {
    if (!email) {
      return null;
    }
    try {
      const res = await this.datastoreService.getByField({
        fieldKey: 'data.email',
        fieldValue: `${email}`,
        documentType: documentType.EMAIL_ACCOUNT,
      });
      return this.unwrapMany(res?.data)[0] ?? null;
    } catch (error) {
      this.logger.debug(
        `Unable to read email account for email ${email}: ${error?.message}`,
      );
      return null;
    }
  }

  /** Reads every email account belonging to a Smartlead client. */
  async readBySmartleadClientId(
    smartleadClientId: string,
    pagination?: { page?: number; pageSize?: number },
  ): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      return [];
    }
    try {
      const res = await this.datastoreService.getByField({
        fieldKey: 'data.smartleadClientId',
        fieldValue: `${smartleadClientId}`,
        documentType: documentType.EMAIL_ACCOUNT,
        pagination: pagination
          ? {
              page: pagination.page ?? 0,
              pageSize: pagination.pageSize ?? DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
            }
          : undefined,
      });
      return this.unwrapMany(res?.data);
    } catch (error) {
      this.logger.debug(
        `Unable to read email accounts for client ${smartleadClientId}: ${error?.message}`,
      );
      return [];
    }
  }

  /** Reads every email account, one page at a time. */
  async readAll(pagination?: {
    page?: number;
    pageSize?: number;
  }): Promise<EmailAccount[]> {
    try {
      const res = await this.datastoreService.getByField({
        fieldKey: 'data.smartleadInboxId',
        fieldValue: { $exists: true },
        documentType: documentType.EMAIL_ACCOUNT,
        pagination: {
          page: pagination?.page ?? 0,
          pageSize: pagination?.pageSize ?? DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
        },
      });
      return this.unwrapMany(res?.data);
    } catch (error) {
      this.logger.debug(`Unable to read email accounts: ${error?.message}`);
      return [];
    }
  }

  /** Deletes an email account by its Smartlead inbox id. */
  async delete(smartleadInboxId: string) {
    await this.datastoreService.remove({
      id: `${smartleadInboxId}`,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    return { message: 'Email account deleted successfully' };
  }

  /**
   * Fetches a single inbox from Smartlead. Returns undefined when Smartlead
   * does not know the inbox.
   */
  static async getRemoteEmailAccount({
    smartleadInboxId,
    email,
    apiKey =<REDACTED>
  }: {
    smartleadInboxId?: string;
    email?: string;
    apiKey?: string;
  }): Promise<Record<string, any> | undefined> {
    const logger = new Logger(EmailAccountEntity.name);
    const matches = (candidate: Record<string, any>) => {
      if (!candidate) {
        return false;
      }
      if (smartleadInboxId && `${candidate.id}` === `${smartleadInboxId}`) {
        return true;
      }
      if (
        email &&
        `${candidate.from_email ?? candidate.email}`.toLowerCase() ===
          `${email}`.toLowerCase()
      ) {
        return true;
      }
      return false;
    };
    const pick = (payload: any): Record<string, any> | undefined => {
      if (!payload) {
        return undefined;
      }
      if (Array.isArray(payload)) {
        return payload.find((candidate) => matches(candidate));
      }
      if (Array.isArray(payload?.data)) {
        return payload.data.find((candidate) => matches(candidate));
      }
      if (payload?.id || payload?.from_email || payload?.email) {
        return payload;
      }
      return undefined;
    };

    const urls: string[] = [];
    if (smartleadInboxId) {
      urls.push(
        `${SMARTLEAD_BASE_URL}/email-accounts/${smartleadInboxId}?api_key=${apiKey}`,
      );
    }
    urls.push(
      `${SMARTLEAD_BASE_URL}/email-accounts/?api_key=${apiKey}&offset=0&limit=1000`,
    );

    for (const url of urls) {
      try {
        const res = await fetch(url);
        const payload = await res?.json();
        const remoteEmailAccount = pick(payload);
        if (remoteEmailAccount) {
          return remoteEmailAccount;
        }
      } catch (error) {
        logger.error(
          `Error fetching email account from Smartlead: ${error?.message}`,
        );
      }
    }
    return undefined;
  }
}

import { Injectable } from '@nestjs/common';
import { DatastoreService } from '../../datastore/datastore.service';
import { EmailAccountEntity } from './emailAccount.entity';

export * from './deliverabilityScore';
export * from './emailAccount.entity';

/**
 * The email infrastructure is made of email accounts (Smartlead inboxes).
 * Kept as a thin alias of {@link EmailAccountEntity} so that existing imports
 * keep working.
 */
@Injectable()
export class EmailInfraEntity extends EmailAccountEntity {
  constructor(datastoreService: DatastoreService) {
    super(datastoreService);
  }
}

import {
  IsArray,
  IsNumber,
  IsOptional,
  IsString,
  IsEmail,
} from 'class-validator';

export class EmailAccountDto {
  /** The id of the inbox inside of Smartlead. Unique key of an email account. */
  @IsOptional()
  @IsString()
  smartleadInboxId?: string;

  @IsEmail()
  email: string;

  @IsString()
  smartleadClientId: string;

  /** Free form tags used to group inboxes. */
  @IsOptional()
  @IsArray()
  tags?: string[];

  /** Campaigns the inbox is associated with. */
  @IsOptional()
  @IsArray()
  campaignIds?: string[];

  /** The numeric warm up reputation. Hydrated from Smartlead when missing. */
  @IsOptional()
  @IsNumber()
  deliverabilityScore?: number;
}

export class EmailAccountListDto {
  @IsNumber()
