arguments.content:
import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
  Optional,
} from '@nestjs/common';
import {
  AssociateEmailAccountsWithCampaignDto,
  EmailAccountDto,
  EmailAccountListDto,
} from './dto/emailAccount.dto';
import { DatastoreService } from '../datastore/datastore.service';
import {
  DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
  DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
  DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  EmailAccount,
  EmailAccountEntity,
} from './entities/emailAccount.entity';

type EmailAccountReference =
  | string
  | (Partial<EmailAccountDto> & Record<string, any>);

@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);
  private emailAccountEntity?: EmailAccountEntity;

  constructor(
    @Optional() private readonly datastoreService?: DatastoreService,
    @Optional() emailAccountEntity?: EmailAccountEntity,
  ) {
    this.emailAccountEntity = emailAccountEntity;
  }

  /**
   * The email account persistence. Resolved lazily so that the service can be
   * used with nothing but a datastore.
   */
  private get emailAccounts(): EmailAccountEntity {
    if (!this.emailAccountEntity) {
      this.emailAccountEntity = new EmailAccountEntity(
        this.datastoreService ? this.datastoreService : new DatastoreService(),
      );
    }
    return this.emailAccountEntity;
  }

  private resolveSmartleadInboxId(
    reference: EmailAccountReference,
  ): string | undefined {
    if (!reference) {
      return undefined;
    }
    if (typeof reference === 'string' || typeof reference === 'number') {
      return `${reference}`;
    }
    const id =
      reference.smartleadInboxId ??
      reference.id ??
      reference.inboxId ??
      reference.emailAccountId;
    return id === undefined || id === null || id === '' ? undefined : `${id}`;
  }

  /**
   * Returns the inboxes that should be used for a campaign.
   *
   * The number of inboxes needed is:
   *   floor(total number of emails / days in the campaign / emails per inbox per day)
   *
   * The inboxes of the Smartlead client are then ranked by:
   *   1. deliverability score, descending
   *   2. number of campaigns already associated, ascending
   *   3. number of other inboxes on the same domain, ascending
   *   4. creation time, oldest first
   *
   * See: https://app.clickup.com/18036112/v/dc/h6dcg-8771/h6dcg-44571
   */
  async getBestEmailAccountsForCampaign({
    smartleadClientId,
    campaignId,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    totalNumberOfEmailsToSend,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: EmailAccountListDto): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    const numberOfInboxesNeeded = EmailAccount.getNumberOfInboxesNeeded({
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign,
      numberOfEmailsPerInboxPerDay,
    });
    this.logger.log(
      `Finding ${numberOfInboxesNeeded} inboxes for campaign ${campaignId} of client ${smartleadClientId}. ` +
        `${totalNumberOfEmailsToSend} emails over ${numberOfDaysInCampaign} days at ${numberOfEmailsPerInboxPerDay} emails per inbox per day`,
    );
    if (numberOfInboxesNeeded <= 0) {
      return [];
    }
    const emailAccounts =
      await this.emailAccounts.readBySmartleadClientId(smartleadClientId);
    if (!emailAccounts?.length) {
      this.logger.log(
        `No email accounts found for smartlead client ${smartleadClientId}`,
      );
      return [];
    }
    return EmailAccount.rank(emailAccounts).slice(0, numberOfInboxesNeeded);
  }

  /**
   * The number of inboxes needed to send a given volume of emails.
   */
  getNumberOfInboxesNeeded({
    totalNumberOfEmailsToSend,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: {
    totalNumberOfEmailsToSend: number;
    numberOfDaysInCampaign?: number;
    numberOfEmailsPerInboxPerDay?: number;
  }): number {
    return EmailAccount.getNumberOfInboxesNeeded({
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign,
      numberOfEmailsPerInboxPerDay,
    });
  }

  /**
   * Associates inboxes with a campaign.
   *
   * The association is idempotent, duplicated inbox ids in the request are
   * treated as a single inbox and the whole request is rejected - without any
   * write - when one of the inboxes cannot be found.
   */
  async associateEmailAccountsWithCampaign({
    emailAccountIds,
    campaignId,
  }: AssociateEmailAccountsWithCampaignDto): Promise<EmailAccount[]> {
    if (!campaignId) {
      throw new BadRequestException('campaignId is required');
    }
    const uniqueEmailAccountIds = (emailAccountIds ? emailAccountIds : [])
      .filter((id) => id !== undefined && id !== null && `${id}` !== '')
      .map((id) => `${id}`)
      .filter((id, index, self) => self.indexOf(id) === index);
    if (!uniqueEmailAccountIds.length) {
      return [];
    }
    const emailAccounts = await Promise.all(
      uniqueEmailAccountIds.map((id) => this.emailAccounts.read(id)),
    );
    const missingEmailAccountIds = uniqueEmailAccountIds.filter(
      (id, index) => !emailAccounts[index],
    );
    if (missingEmailAccountIds.length) {
      throw new NotFoundException(
        `Email accounts not found: ${missingEmailAccountIds.join(', ')}`,
      );
    }
    const updatedEmailAccounts: EmailAccount[] = [];
    for (const emailAccount of emailAccounts) {
      const changed = emailAccount.addCampaign(campaignId);
      if (changed) {
        updatedEmailAccounts.push(await this.emailAccounts.create(emailAccount));
      } else {
        this.logger.log(
          `Email account ${emailAccount.smartleadInboxId} is already associated with campaign ${campaignId}`,
        );
        updatedEmailAccounts.push(emailAccount);
      }
    }
    return updatedEmailAccounts;
  }

  /**
   * Creates (or updates) an email account. The creation time and the warm up
   * reputation are always hydrated from Smartlead.
   */
  async saveEmailAccount(
    emailAccount: EmailAccountDto & Record<string, any>,
  ): Promise<EmailAccount> {
    const requested = new EmailAccount(emailAccount ? emailAccount : {});
    if (!requested.smartleadInboxId && !requested.email) {
      throw new BadRequestException(
        'smartleadInboxId or email is required to save an email account',
      );
    }
    const remoteEmailAccount = await EmailAccountEntity.getRemoteEmailAccount({
      smartleadInboxId: requested.smartleadInboxId,
      email: requested.email,
    });
    if (!remoteEmailAccount) {
      throw new NotFoundException(
        `Email account ${requested.smartleadInboxId ?? requested.email} not found in Smartlead`,
      );
    }
    const existingEmailAccount = requested.smartleadInboxId
      ? await this.emailAccounts.read(requested.smartleadInboxId)
      : await this.emailAccounts.readByEmail(requested.email);
    const campaignIds = [
      ...(existingEmailAccount ? existingEmailAccount.campaignIds : []),
      ...requested.campaignIds,
    ];
    const tags = [
      ...(existingEmailAccount ? existingEmailAccount.tags : []),
      ...requested.tags,
    ];
    const entity = EmailAccount.fromSmartleadEmailAccount(remoteEmailAccount, {
      smartleadInboxId:
        requested.smartleadInboxId ??
        (remoteEmailAccount.id ? `${remoteEmailAccount.id}` : undefined),
      email: requested.email,
      smartleadClientId: requested.smartleadClientId,
      tags,
      campaignIds,
    });
    return this.emailAccounts.create(entity);
  }

  /** Reads an email account by its Smartlead inbox id (or email). */
  async getEmailAccount(
    emailAccount: EmailAccountReference,
  ): Promise<EmailAccount> {
    const smartleadInboxId = this.resolveSmartleadInboxId(emailAccount);
    const email =
      typeof emailAccount === 'object' && emailAccount
        ? emailAccount.email
        : undefined;
    const found = smartleadInboxId
      ? await this.emailAccounts.read(smartleadInboxId)
      : await this.emailAccounts.readByEmail(email);
    if (!found) {
      throw new NotFoundException(
        `Email account ${smartleadInboxId ?? email} not found`,
      );
    }
    return found;
  }

  /** Alias of {@link getEmailAccount}. */
  async getEmailAccountById(smartleadInboxId: string): Promise<EmailAccount> {
    return this.getEmailAccount(smartleadInboxId);
  }

  /** Lists email accounts, one page at a time. */
  async getAllEmailAccounts(pagination?: {
    page?: number;
    pageSize?: number;
  }): Promise<EmailAccount[]> {
    const page = pagination?.page ?? 0;
    const pageSize = pagination?.pageSize ?? DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE;
    this.logger.log(`Getting email accounts page ${page} of size ${pageSize}`);
    return this.emailAccounts.readAll({ page, pageSize });
  }

  /** Reads an email account by its email address. */
  async getEmailAccountByEmail(email: string): Promise<EmailAccount> {
    const emailAccount = await this.emailAccounts.readByEmail(email);
    if (!emailAccount) {
      throw new NotFoundException(`Email account ${email} not found`);
    }
    return emailAccount;
  }

  /** Reads every email account owned by a Smartlead client. */
  async getEmailAccountBySmartleadClientId(
    smartleadClientId: string,
    pagination?: { page?: number; pageSize?: number },
  ): Promise<EmailAccount[]> {
    return this.emailAccounts.readBySmartleadClientId(
      smartleadClientId,
      pagination,
    );
  }

  /** Alias of {@link getEmailAccountBySmartleadClientId}. */
  async getEmailAccountsBySmartleadClientId(
    smartleadClientId: string,
    pagination?: { page?: number; pageSize?: number },
  ): Promise<EmailAccount[]> {
    return this.getEmailAccountBySmartleadClientId(
      smartleadClientId,
      pagination,
    );
  }

  /** Deletes an email account. */
  async deleteEmailAccount(
    emailAccount: EmailAccountReference,
  ): Promise<{ message: string }> {
    const smartleadInboxId = this.resolveSmartleadInboxId(emailAccount);
    if (!smartleadInboxId) {
      throw new BadRequestException('smartleadInboxId is required');
    }
    this.logger.log(`Deleting email account ${smartleadInboxId}`);
    return this.emailAccounts.delete(smartleadInboxId);
  }

  /**
   * Imports the inboxes of a Smartlead client into the email account datastore.
   * Used by the import script.
   */
  async importEmailAccountsFromSmartlead({
    smartleadClientId,
    emails,
    tags = [],
  }: {
    smartleadClientId: string;
    emails?: string[];
    tags?: string[];
  }): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    const importedEmailAccounts: EmailAccount[] = [];
    for (const email of emails ? emails : []) {
      try {
        importedEmailAccounts.push(
          await this.saveEmailAccount({
            email,
            smartleadClientId,
            tags,
          } as EmailAccountDto),
        );
      } catch (error) {
        this.logger.error(`Error importing email account ${email}: ${error}`);
      }
    }
    return importedEmailAccounts;
  }

  /**
   * Refreshes the deliverability score (warm up reputation) of the stored
   * inboxes from Smartlead. Used by the reputation sync script.
   */
  async syncEmailAccountDeliverabilityScores({
    smartleadClientId,
    page = 0,
    pageSize = DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
  }: {
    smartleadClientId?: string;
    page?: number;
    pageSize?: number;
  } = {}): Promise<EmailAccount[]> {
    const emailAccounts = smartleadClientId
      ? await this.emailAccounts.readBySmartleadClientId(smartleadClientId, {
          page,
          pageSize,
        })
      : await this.emailAccounts.readAll({ page, pageSize });
    const syncedEmailAccounts: EmailAccount[] = [];
    for (const emailAccount of emailAccounts) {
      const remoteEmailAccount = await EmailAccountEntity.getRemoteEmailAccount(
        {
          smartleadInboxId: emailAccount.smartleadInboxId,
          email: emailAccount.email,
        },
      );
      if (!remoteEmailAccount) {
        this.logger.error(
          `Email account ${emailAccount.smartleadInboxId} no longer exists in Smartlead`,
        );
        continue;
      }
      emailAccount.setDeliverabilityScore(
        remoteEmailAccount?.warmup_details?.warmup_reputation ??
          remoteEmailAccount?.warmup_reputation,
      );
      if (!emailAccount.createdAt && remoteEmailAccount?.created_at) {
        emailAccount.createdAt = `${remoteEmailAccount.created_at}`;
      }
      syncedEmailAccounts.push(await this.emailAccounts.create(emailAccount));
    }
    return syncedEmailAccounts;
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { EmailinfraService } from './emailinfra.service';
import {
  AssociateEmailAccountsWithCampaignDto,
  EmailAccountDto,
  EmailAccountListDto,
} from './dto/emailAccount.dto';

@Controller('emailinfra')
export class EmailinfraController {
  constructor(private readonly emailinfraService: EmailinfraService) {}

  @UseGuards(AuthGuard('api-key'))
  @Post('/email-account')
  saveEmailAccount(@Body() emailAccountDto: EmailAccountDto) {
    return this.emailinfraService.saveEmailAccount(emailAccountDto);
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('/email-account')
  getAllEmailAccounts(
    @Query('page') page?: number,
    @Query('pageSize') pageSize?: number,
  ) {
    return this.emailinfraService.getAllEmailAccounts({
      page: page ? Number(page) : undefined,
      pageSize: pageSize ? Number(pageSize) : undefined,
    });
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('/email-account/email/:email')
  getEmailAccountByEmail(@Param('email') email: string) {
    return this.emailinfraService.getEmailAccountByEmail(email);
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('/email-account/client/:smartleadClientId')
  getEmailAccountBySmartleadClientId(
    @Param('smartleadClientId') smartleadClientId: string,
    @Query('page') page?: number,
    @Query('pageSize') pageSize?: number,
  ) {
    return this.emailinfraService.getEmailAccountBySmartleadClientId(
      smartleadClientId,
      page || pageSize
        ? {
            page: page ? Number(page) : undefined,
            pageSize: pageSize ? Number(pageSize) : undefined,
          }
        : undefined,
    );
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('/email-account/:smartleadInboxId')
  getEmailAccount(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.getEmailAccount(smartleadInboxId);
  }

  @UseGuards(AuthGuard('api-key'))
  @Delete('/email-account/:smartleadInboxId')
  deleteEmailAccount(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.deleteEmailAccount(smartleadInboxId);
  }

  @UseGuards(AuthGuard('api-key'))
  @Post('/email-account/campaign')
  associateEmailAccountsWithCampaign(
    @Body()
    associateEmailAccountsWithCampaignDto: AssociateEmailAccountsWithCampaignDto,
  ) {
    return this.emailinfraService.associateEmailAccountsWithCampaign(
      associateEmailAccountsWithCampaignDto,
    );
  }

  @UseGuards(AuthGuard('api-key'))
  @Post('/email-account/best')
  getBestEmailAccountsForCampaign(
    @Body() emailAccountListDto: EmailAccountListDto,
  ) {
    return this.emailinfraService.getBestEmailAccountsForCampaign(
      emailAccountListDto,
    );
  }

  @UseGuards(AuthGuard('api-key'))
  @Post('/email-account/import')
  importEmailAccountsFromSmartlead(
    @Body()
    body: {
      smartleadClientId: string;
      emails?: string[];
      tags?: string[];
    },
  ) {
    return this.emailinfraService.importEmailAccountsFromSmartlead(body);
  }

  @UseGuards(AuthGuard('api-key'))
  @Post('/email-account/sync-reputation')
  syncEmailAccountDeliverabilityScores(
    @Body()
    body?: {
      smartleadClientId?: string;
      page?: number;
      pageSize?: number;
    },
  ) {
    return this.emailinfraService.syncEmailAccountDeliverabilityScores(
      body ? body : {},
    );
  }
}

