/**
 * A tiny in memory stand in for the datastore so that the email account
 * infrastructure can be exercised end to end.
 */
class InMemoryDatastore {
  public documents = new Map<string, any>();

  async store({ data, context }: any) {
    this.documents.set(`${context?.uniqueId}`, JSON.parse(JSON.stringify(data)));
    return { message: 'Data stored successfully', uniqueId: context?.uniqueId };
  }

  async getById({ id }: any) {
    return { data: this.documents.get(`${id}`), message: 'ok' };
  }

  async getByField({ fieldKey, fieldValue, pagination }: any) {
    const key = `${fieldKey}`.replace('data.', '');
    let data = [...this.documents.values()].filter((document) => {
      if (fieldValue && typeof fieldValue === 'object') {
        return document[key] !== undefined;
      }
      return `${document[key]}` === `${fieldValue}`;
    });
    if (pagination) {
      const start = pagination.page * pagination.pageSize;
      data = data.slice(start, start + pagination.pageSize);
    }
    return { data: data.length ? data : undefined, message: 'ok' };
  }

  async remove({ id }: any) {
    this.documents.delete(`${id}`);
    return { message: 'Data removed successfully' };
  }
}

