describe('Email account infrastructure', () => {
  let service: EmailinfraService;
  let datastore: InMemoryDatastore;

  const save = async (
    remoteEmailAccount: Record<string, any>,
    dto: Partial<EmailAccountDto> = {},
  ) => {
    jest
      .spyOn(EmailAccountEntity, 'getRemoteEmailAccount')
      .mockResolvedValueOnce(remoteEmailAccount);
    return service.saveEmailAccount({
      smartleadInboxId: `${remoteEmailAccount.id}`,
      email: remoteEmailAccount.from_email,
      smartleadClientId: `${remoteEmailAccount.client_id}`,
      ...dto,
    } as EmailAccountDto);
  };

  beforeEach(() => {
    datastore = new InMemoryDatastore();
    service = new EmailinfraService(
      datastore as unknown as DatastoreService,
      new EmailAccountEntity(datastore as unknown as DatastoreService),
    );
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('the email account model', () => {
    it('keeps the smartlead client and email, and derives the domain', () => {
      const emailAccount = new EmailAccount({
        smartleadInboxId: '1',
        email: 'Sales@Tenex.Email',
        smartleadClientId: '1234',
      });
      expect(emailAccount.smartleadInboxId).toBe('1');
      expect(emailAccount.email).toBe('Sales@Tenex.Email');
      expect(emailAccount.smartleadClientId).toBe('1234');
      expect(emailAccount.domain).toBe('tenex.email');
      expect(emailAccount.tags).toEqual([]);
      expect(emailAccount.campaignIds).toEqual([]);
      expect(emailAccount.numberOfCampaignAssociated).toBe(0);
    });

    it('exposes the number of associated campaigns', () => {
      const emailAccount = new EmailAccount({
        smartleadInboxId: '1',
        email: 'sales@tenex.email',
        campaignIds: ['a', 'b', 'a'],
      });
      expect(emailAccount.campaignIds).toEqual(['a', 'b']);
      expect(emailAccount.numberOfCampaignAssociated).toBe(2);
    });

    it('keeps the numeric warm up reputation and maps the band', () => {
      const bandFor = (deliverabilityScore?: number) =>
        new EmailAccount({ smartleadInboxId: '1', deliverabilityScore })
          .deliverabilityScoreBand;
      expect(bandFor(100)).toBe(DeliverabilityScoreBand.High);
      expect(bandFor(99)).toBe(DeliverabilityScoreBand.Medium);
      expect(bandFor(98)).toBe(DeliverabilityScoreBand.Medium);
      expect(bandFor(97)).toBe(DeliverabilityScoreBand.Low);
      expect(bandFor(95)).toBe(DeliverabilityScoreBand.Low);
      expect(bandFor(94)).toBe(DeliverabilityScoreBand.Burned);
      expect(bandFor(0)).toBe(DeliverabilityScoreBand.Burned);
      expect(bandFor(undefined)).toBe(DeliverabilityScoreBand.Unknown);
      const emailAccount = new EmailAccount({
        smartleadInboxId: '1',
        deliverabilityScore: 98,
      });
      expect(emailAccount.deliverabilityScore).toBe(98);
    });
  });

  describe('saveEmailAccount', () => {
    it('hydrates the creation time and the warm up reputation from smartlead', async () => {
      const emailAccount = await save(
        smartleadInbox('11', {
          created_at: '2023-05-04T10:00:00.000Z',
          warmup_details: { warmup_reputation: '96%' },
        }),
      );
      expect(emailAccount.smartleadInboxId).toBe('11');
      expect(emailAccount.createdAt).toBe('2023-05-04T10:00:00.000Z');
      expect(emailAccount.deliverabilityScore).toBe(96);
      expect(emailAccount.deliverabilityScoreBand).toBe(
        DeliverabilityScoreBand.Low,
      );
      expect(datastore.documents.get('11')).toBeDefined();
    });

    it('throws when the inbox does not exist in smartlead', async () => {
      jest
        .spyOn(EmailAccountEntity, 'getRemoteEmailAccount')
        .mockResolvedValueOnce(undefined);
      await expect(
        service.saveEmailAccount({
          smartleadInboxId: 'missing',
          email: 'missing@tenex.email',
          smartleadClientId: '1234',
        } as EmailAccountDto),
      ).rejects.toThrow(NotFoundException);
      expect(datastore.documents.size).toBe(0);
    });
  });

  describe('lookups and deletion', () => {
    beforeEach(async () => {
      await save(smartleadInbox('1'), { tags: ['warmed'] });
      await save(smartleadInbox('2', { client_id: 9999 }));
    });

    it('reads by id, email and smartlead client', async () => {
      expect((await service.getEmailAccount('1')).email).toBe(
        'sales1@tenex.email',
      );
      expect(
        (await service.getEmailAccountByEmail('sales2@tenex.email'))
          .smartleadInboxId,
      ).toBe('2');
      const clientEmailAccounts =
        await service.getEmailAccountBySmartleadClientId('1234');
      expect(clientEmailAccounts.map((a) => a.smartleadInboxId)).toEqual(['1']);
    });

    it('lists email accounts with pagination', async () => {
      expect(await service.getAllEmailAccounts()).toHaveLength(2);
      const firstPage = await service.getAllEmailAccounts({
        page: 0,
        pageSize: 1,
      });
      expect(firstPage).toHaveLength(1);
      const secondPage = await service.getAllEmailAccounts({
        page: 1,
        pageSize: 1,
      });
      expect(secondPage).toHaveLength(1);
      expect(firstPage[0].smartleadInboxId).not.toBe(
        secondPage[0].smartleadInboxId,
      );
    });

    it('throws when the email account does not exist', async () => {
      await expect(service.getEmailAccount('nope')).rejects.toThrow(
        NotFoundException,
      );
    });

    it('deletes an email account', async () => {
      await service.deleteEmailAccount('1');
      expect(datastore.documents.has('1')).toBe(false);
      await expect(service.getEmailAccount('1')).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe('associateEmailAccountsWithCampaign', () => {
    beforeEach(async () => {
      await save(smartleadInbox('1'));
      await save(smartleadInbox('2'));
    });

    it('treats repeated inbox ids as a single inbox and is idempotent', async () => {
      const associated = await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['1', '1', '2'],
        campaignId: 'campaign-a',
      });
      expect(associated).toHaveLength(2);
      expect(associated[0].campaignIds).toEqual(['campaign-a']);
      expect(associated[0].numberOfCampaignAssociated).toBe(1);

      await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['1'],
        campaignId: 'campaign-a',
      });
      const emailAccount = await service.getEmailAccount('1');
      expect(emailAccount.campaignIds).toEqual(['campaign-a']);
      expect(emailAccount.numberOfCampaignAssociated).toBe(1);
    });

    it('rejects the whole request without writing when an inbox is missing', async () => {
      await expect(
        service.associateEmailAccountsWithCampaign({
          emailAccountIds: ['1', 'missing'],
          campaignId: 'campaign-a',
        }),
      ).rejects.toThrow(NotFoundException);
      expect((await service.getEmailAccount('1')).campaignIds).toEqual([]);
    });
  });

  describe('getBestEmailAccountsForCampaign', () => {
    it('computes the number of inboxes needed', () => {
      expect(
        service.getNumberOfInboxesNeeded({ totalNumberOfEmailsToSend: 500 }),
      ).toBe(2);
      expect(
        service.getNumberOfInboxesNeeded({
          totalNumberOfEmailsToSend: 600,
          numberOfDaysInCampaign: 10,
          numberOfEmailsPerInboxPerDay: 20,
        }),
      ).toBe(3);
      expect(
        service.getNumberOfInboxesNeeded({
          totalNumberOfEmailsToSend: 100,
          numberOfDaysInCampaign: 10,
          numberOfEmailsPerInboxPerDay: 20,
        }),
      ).toBe(0);
    });

    it('ranks by score, campaigns, domain spread and creation time', async () => {
      await save(
        smartleadInbox('low-score', {
          warmup_details: { warmup_reputation: '95%' },
        }),
      );
      await save(
        smartleadInbox('busy', {
          from_email: 'busy@one.email',
          created_at: '2020-01-01T00:00:00.000Z',
        }),
      );
      await save(
        smartleadInbox('crowded', { from_email: 'crowded@crowded.email' }),
      );
      await save(
        smartleadInbox('crowded-sibling', {
          from_email: 'sibling@crowded.email',
        }),
      );
      await save(
        smartleadInbox('oldest', {
          from_email: 'oldest@unique.email',
          created_at: '2019-01-01T00:00:00.000Z',
        }),
      );
      await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['busy'],
        campaignId: 'other-campaign',
      });

      const best = await service.getBestEmailAccountsForCampaign({
        smartleadClientId: '1234',
        campaignId: 'campaign-a',
        totalNumberOfEmailsToSend: 800,
        numberOfDaysInCampaign: 10,
        numberOfEmailsPerInboxPerDay: 20,
      });
      expect(best.map((emailAccount) => emailAccount.smartleadInboxId)).toEqual([
        'oldest',
        'crowded',
        'crowded-sibling',
        'busy',
      ]);
    });

    it('returns nothing when the client has no inboxes', async () => {
      expect(
        await service.getBestEmailAccountsForCampaign({
          smartleadClientId: 'unknown-client',
          campaignId: 'campaign-a',
          totalNumberOfEmailsToSend: 500,
        }),
      ).toEqual([]);
    });
  });
});

