/**
 * Imports warmed Smartlead inboxes into the email account datastore.
 *
 * The script reads a CSV with the columns:
 *   email,smartleadClientId,smartleadInboxId,tags
 * (`smartleadInboxId` and `tags` are optional, tags are separated by `|`)
 *
 * Usage:
 *   node client/tools/importEmailAccounts.js ./inboxes.csv
 *
 * The creation time and the warm up reputation of every inbox are hydrated
 * from Smartlead by the API, so only the email and the Smartlead client are
 * required here.
 */
const fs = require('fs');
const csv = require('csv-parser');

const BASE_URL =
  process.env.TENEX_API_URL || 'https://internal.prod.tenex.email';
const API_KEY = process.env.TENEX_API_KEY || '';
const API_ENDPOINT = `${BASE_URL}/emailinfra/email-account`;
const inputCsvPath = process.argv[2] || './emailAccounts.csv';

const postEmailAccount = async (emailAccount) => {
  const response = await fetch(API_ENDPOINT, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-API-KEY': API_KEY,
    },
    body: JSON.stringify(emailAccount),
  });
  if (!response.ok) {
    throw new Error(
      `API error for ${emailAccount.email}: ${response.status} ${response.statusText}`,
    );
  }
  return response.json();
};

const readRows = (path) =>
  new Promise((resolve, reject) => {
    const rows = [];
    fs.createReadStream(path)
      .pipe(csv())
      .on('data', (row) => {
        if (!row.email) {
          return;
        }
        rows.push({
          email: `${row.email}`.trim(),
          smartleadClientId: `${row.smartleadClientId || ''}`.trim(),
          smartleadInboxId: row.smartleadInboxId
            ? `${row.smartleadInboxId}`.trim()
            : undefined,
          tags: row.tags
            ? `${row.tags}`
                .split('|')
                .map((tag) => tag.trim())
                .filter(Boolean)
            : [],
        });
      })
      .on('end', () => resolve(rows))
      .on('error', reject);
  });

const main = async () => {
  const rows = await readRows(inputCsvPath);
  console.log(`Importing ${rows.length} email accounts from ${inputCsvPath}`);
  let imported = 0;
  for (const row of rows) {
    try {
      const emailAccount = await postEmailAccount(row);
      imported++;
      console.log(
        `[${imported}/${rows.length}] ${emailAccount.email} -> inbox ${emailAccount.smartleadInboxId} (${emailAccount.deliverabilityScore} / ${emailAccount.deliverabilityScoreBand})`,
      );
    } catch (error) {
      console.error(`Error importing ${row.email}: ${error?.message}`);
    }
  }
  console.log(`Imported ${imported} of ${rows.length} email accounts`);
};

main()
  .then(() => console.log('Done'))
  .catch((error) => {
    console.error(`Error importing email accounts: ${error?.message}`);
    process.exit(1);
  });

/**
 * Refreshes the deliverability score (Smartlead warm up reputation) of the
 * stored email accounts and prints the resulting bands.
 *
 * Usage:
 *   node client/tools/syncEmailAccountReputation.js [smartleadClientId]
 */
const BASE_URL =
  process.env.TENEX_API_URL || 'https://internal.prod.tenex.email';
const API_KEY = process.env.TENEX_API_KEY || '';
const API_ENDPOINT = `${BASE_URL}/emailinfra/email-account/sync-reputation`;
const smartleadClientId = process.argv[2];
const PAGE_SIZE = Number(process.env.PAGE_SIZE || 100);

const syncPage = async (page) => {
  const response = await fetch(API_ENDPOINT, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-API-KEY': API_KEY,
    },
    body: JSON.stringify({ smartleadClientId, page, pageSize: PAGE_SIZE }),
  });
  if (!response.ok) {
    throw new Error(`API error: ${response.status} ${response.statusText}`);
  }
  return response.json();
};

const main = async () => {
  let page = 0;
  let synced = 0;
  // eslint-disable-next-line no-constant-condition
  while (true) {
    const emailAccounts = await syncPage(page);
    if (!emailAccounts || emailAccounts.length === 0) {
      break;
    }
    emailAccounts.forEach((emailAccount) => {
      console.log(
        `${emailAccount.email} -> ${emailAccount.deliverabilityScore} (${emailAccount.deliverabilityScoreBand}) - ${emailAccount.numberOfCampaignAssociated} campaigns`,
      );
    });
    synced += emailAccounts.length;
    if (emailAccounts.length < PAGE_SIZE) {
      break;
    }
    page++;
  }
  console.log(`Synced ${synced} email accounts`);
};

main()
  .then(() => console.log('Done'))
  .catch((error) => {
    console.error(`Error syncing email account reputations: ${error?.message}`);
    process.exit(1);
  });

